//! Four-color gradient fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){
 let mut cases=vec![];
 for (w,h) in [(1,7),(7,1),(6,4),(18,10)] {for blend in [1.0,100.0,500.0,1000.0] {for opacity in [0.0,25.0,100.0] {for alternate in [false,true] {
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let input:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2] as f32/255.0)*a,a]}).collect();
  let colors=if alternate {[[-1.0,2.0,0.5,0.0],[0.25,0.5,0.75,-1.0],[1.0,0.0,0.0,2.0],[0.0,1.0,1.0,0.0]]}else{[[1.0,1.0,0.0,1.0],[0.0,1.0,0.0,1.0],[1.0,0.0,1.0,1.0],[0.0,0.0,1.0,1.0]]};
  let mut image=Image{w,h,px:input};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="four_color_gradient").unwrap().instance();
  for (name,color) in ["c1","c2","c3","c4"].iter().zip(colors){effect.params.insert((*name).into(),Param::new(ParamValue::Color(color)));}
  effect.params.insert("blend".into(),Param::new(ParamValue::Float(blend)));
  effect.params.insert("opacity".into(),Param::new(ParamValue::Float(opacity)));
  let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.0,seconds:0.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  cases.push(json!({"parameters":{"c1":colors[0],"c2":colors[1],"c3":colors[2],"c4":colors[3],"blend":blend,"opacity":opacity},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}}
 let mut media=vec![];
 for tick in [0u64,250000,500000] {
  let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,if i%16<8&&i/16<12 {128}else{0}]}).collect();
  let mut frames=vec![];
  for index in 0..(1000000-tick).div_ceil(100000) {
   let local=(tick+index*100000).min(500000);let progress=local as f64/500000.0;
   let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
   let mut image=Image{w:16,h:16,px};
   let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="four_color_gradient").unwrap().instance();
   let base=[[1.0,1.0,0.0,1.0],[0.0,1.0,0.0,1.0],[1.0,0.0,1.0,1.0],[0.0,0.0,1.0,1.0]];
   for(name,start)in ["c1","c2","c3","c4"].iter().zip(base){
    let color=start.map(|v| (v+(1.0-2.0*v)*progress) as f32);
    effect.params.insert((*name).into(),Param::new(ParamValue::Color(color)));
   }
   effect.params.insert("blend".into(),Param::new(ParamValue::Float(1.0+progress*999.0)));
   effect.params.insert("opacity".into(),Param::new(ParamValue::Float(25.0+progress*75.0)));
   let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.0,seconds:local as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
   apply(&mut image,&effect,&cx);frames.push(image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());
  }
  media.push(json!({"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
 }
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));
}
